demo.css:
#stage { position: relative; height: 180px; }
.c {
  position: absolute; left: 50%; top: 50%;
  width: 10px; height: 16px; border-radius: 2px;
  background: hsl(random(0, 360) 85% 60%);
  translate: random(calc(var(--spread) * -1), var(--spread)) random(calc(var(--spread) * -0.6), calc(var(--spread) * 0.6));
  rotate: random(0deg, 360deg);
}
button { font: 14px var(--demo-sans); padding: 6px 12px; }

demo.js:
function go() {
  const s = document.getElementById('stage');
  s.replaceChildren(...Array.from({ length: 40 }, () => {
    const d = document.createElement('i');
    d.className = 'c';
    return d;
  }));
}
document.getElementById('go').onclick = go;
go();

fallback.css:
#stage { position: relative; height: 180px; }
.c { position: absolute; left: 50%; top: 50%; width: 10px; height: 16px; border-radius: 2px; }
button { font: 14px var(--demo-sans); padding: 6px 12px; }

fallback.js:
function go() {
  const s = document.getElementById('stage');
  const sp = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--spread')) || 110;
  const r = (a, b) => a + Math.random() * (b - a);
  s.replaceChildren(...Array.from({ length: 40 }, () => {
    const d = document.createElement('i');
    d.className = 'c';
    d.style.background = `hsl(${r(0, 360)} 85% 60%)`;
    d.style.translate = `${r(-sp, sp)}px ${r(-sp * 0.6, sp * 0.6)}px`;
    d.style.rotate = `${r(0, 360)}deg`;
    return d;
  }));
}
document.getElementById('go').onclick = go;
go();

